function resetBrand(){state.brand=clone(DEFAULT_BRAND);saveDraft();loadDefaultLogo();openBrand();renderPreview()}
function pickBrandLogo(){$('csBrandLogoInput').click()}
function openHistory(){renderHistory();openModal('csHistoryModal')}
