function printNow(){try{let html=printDocument();recordHistory('طباعة');logOperation('print','طباعة الكروت',expandedJobs().length+' كارت • '+state.output);if(window.Android&&Android.printHtml)return Android.printHtml(html);let frame=$('csPrintFrame');frame.srcdoc=html;openModal('csPrintModal');setTimeout(()=>frame.contentWindow&&frame.contentWindow.print(),700)}catch(e){alert(e.message)}}
function savePdf(){try{let html=printDocument(),name='Abu_Bassam_Cards_'+Date.now()+'.pdf';recordHistory('حفظ PDF');logOperation('pdf','حفظ الكروت PDF',expandedJobs().length+' كارت • '+state.output);if(window.Android&&Android.savePdfHtml)return Android.savePdfHtml(name,html);previewPrint();alert('حفظ PDF المباشر متاح داخل تطبيق Android')}catch(e){alert(e.message)}}
async function exportPng(){try{let pages=[],labels=[],stamp=Date.now();if(state.sides!=='back'){pages.push(await domCardPng('front'));labels.push('الأمامي')}if(state.sides!=='front'){pages.push(await domCardPng('back'));labels.push('الخلفي')}recordHistory('حفظ '+labels.join(' و')+' في المعرض');if(window.Android&&Android.savePagesToGallery)Android.savePagesToGallery('Abu_Bassam_Card_'+labels.join('_'),JSON.stringify(pages),'image/png');else pages.forEach((data,index)=>setTimeout(()=>saveImage('Abu_Bassam_Card_'+labels[index]+'_'+stamp+'.png','image/png',data),index*250));logOperation('gallery','حفظ أوجه الكارت كصور مستقلة',TYPE_LABELS[state.type]+' • '+labels.join(' و'))}catch(e){alert('تعذر إنشاء صور الكارت على هذا الجهاز. استخدم PDF عالي الجودة.')}}
