function importOcrText(text){let lines=String(text||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean),account='',password='';for(let line of lines){let email=line.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(email&&!account)account=email[0];if(!account&&/(?:الحساب|البريد|email|user(?:name)?|phone)\s*[:：-]/i.test(line))account=line.replace(/^.*?[:：-]\s*/,'').trim();if(!password&&/(?:كلمة\s*السر|الرمز|password|pass)\s*[:：-]/i.test(line))password=line.replace(/^.*?[:：-]\s*/,'').trim()}if(!account)account=lines[0]||'';if(!password)password=lines.find(line=>line!==account&&!/@/.test(line))||'';state.type='login';state.forms.login.account=account;state.forms.login.password=password;saveDraft();renderAll();alert('تم توزيع النص على حقول الحساب وكلمة السر. راجعهما قبل الطباعة.')}
